mapper.select:
select *
from t_r_data_perm_user_direct_grant
where user_id = #{userId}
  and effective_time <= #{asOf}
  and (expiration_time is null or expiration_time > #{asOf})
order by effective_time desc, id desc

select *
from t_r_data_perm_user_direct_grant
where user_id = #{userId}
  and expiration_time is not null
  and expiration_time <= #{now}
order by expiration_time desc

select count(*)
from t_r_data_perm_user_direct_grant
where scope_code = #{scopeCode}
